const hubIcon=name=>`<svg class="hub-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${hubIconPaths[name]||hubIconPaths.people}</svg>`;
const shortcutIcons={archive:'book',reviews:'review','ask-scf':'chat',travel:'bus',places:'food','school-links':'link'};
const groupCategoryIcons={'All groups':'people','Academic & Tech':'code','Faith & Fellowship':'heart','Arts & Creativity':'palette',Volunteering:'heart','Culture & Community':'globe'};
const groupActivityIcons={'Academic & Tech':['code','book','review'],'Faith & Fellowship':['people','heart','globe'],'Arts & Creativity':['palette','chat','people'],Volunteering:['heart','people','check'],'Culture & Community':['globe','people','calendar']};
const link=(url,text)=>`<a class="link" href="#${url}">${text}</a>`;
const searchIcon="<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" aria-hidden=\"true\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 4.5 4.5\"/></svg>";
const btn=(url,text,cls='')=>`<a class="btn ${cls}" href="#${url}">${text} </a>`;
const note='<p class="sample-note">Explore the design: listings, dates, prices and reviews on this preview are illustrative, pending verification by SCF.</p>';
const ad=(side=false)=>side?`<aside class="sidebar-ad"><span class="ad-label">Advertisement · Sample</span><h3>Got a business idea?</h3><p>Put your business online with a website people can actually use.</p><div class="gold-line"></div><b>KOADLABS</b><p>Let’s build something.</p><button class="btn navy" data-ad>Explore services</button></aside>`:`<div class="ad"><div class="ad-monogram">K.<small>KOADLABS</small></div><div><span class="ad-label">Advertisement · Sample placement</span><h3>That business needs a website.</h3><p>Let people find you, see what you offer and get in touch.</p></div><button class="btn" data-ad>Meet Koadlabs </button></div>`;
const intro=(title,desc,tabs='')=>`<div class="page-intro"><div class="wrap"><div class="breadcrumb"><a href="#home">The Hub</a> &nbsp; <span aria-hidden="true">›</span> &nbsp; ${title}</div><h1>${title}</h1><p class="lede">${desc}</p>${tabs}</div></div>`;
const academicTabs=active=>`<div class="tabs" data-motion-tabs="academic" role="navigation" aria-label="Academic pages">${[['archive','book','Academic Archive'],['reviews','review','Course Reviews'],['issues','chat','Academic Issues']].map(([route,icon,label])=>`<a class="${active===route?'selected':''}" href="#${route}" ${active===route?'aria-current="page"':''}>${hubIcon(icon)}<span>${label}</span></a>`).join('')}</div>`;
function card(img,tag,title,desc,route,cta){return `<article class="card"><a href="#${route}" tabindex="-1"><img src="assets/${img}.jpg" alt="${esc(title)}" loading="lazy"></a><div class="card-body"><span class="tag">${tag}</span><h3><a href="#${route}">${title}</a></h3><p>${desc}</p>${link(route,cta)}</div></article>`}
function home(){return `<section class="home-hero"><div class="wrap home-hero-grid"><div class="home-hero-copy"><h1><span>MU IS A LOT.</span><strong>TRUST US,<br>WE GET IT.</strong></h1><p>Past questions, food spots, school updates and a way home. The useful stuff in one place, so you don’t have to keep asking around.</p><form class="home-search" id="home-hub-search" role="search"><label class="sr-only" for="home-search-query">Search the hub</label><input id="home-search-query" type="search" placeholder="What do you need?" maxlength="150"><button type="submit" aria-label="Search the hub">${searchIcon}</button></form><div class="home-hero-actions">${btn('archive','Find study materials','navy')}${link('freshers','New here? Start here')}</div></div><figure class="home-campus-photo"><span class="home-design-stamp" aria-hidden="true">MADE<br>FOR YOU</span><img src="assets/mu-garden.webp" alt="Maduka University’s Love Garden and campus paths" width="1280" height="1024" fetchpriority="high"><figcaption><span>Maduka University</span><span>Made for you.</span></figcaption></figure></div></section>
<section class="home-quick-section"><div class="wrap home-quick-grid">${[['archive','Study materials','Past questions, notes and resources.'],['reviews','Course reviews','Know what you’re getting into.'],['ask-scf','Ask SCF','Something wrong? Tell us.'],['travel','Travel home','Routes, fares and departures.'],['places','Eat, Drink & Shop','What’s available, and how much?'],['school-links','Official school links','Portals, forms and contacts.']].map((s,i)=>`<a href="#${s[0]}"><span class="quick-icon" aria-hidden="true">${hubIcon(shortcutIcons[s[0]])}</span><div><h2>${s[1]}</h2><p>${s[2]}</p></div></a>`).join('')}</div></section>
<section class="section home-updates"><div class="wrap"><div class="section-head"><div><h2>In case you missed it.</h2><p>A few useful places to catch up.</p></div>${link('news','All news & events')}</div><div class="home-update-grid"><a class="home-feature-update" href="#freshers"><img src="assets/mu-orientation.webp" alt="The entrance to Maduka University" loading="lazy" width="900" height="600"><div><h3>Just got here?</h3><p>The forms, packing information and school contacts you’ll want to find first.</p><span class="inline-action">Read the freshers’ guide</span></div></a><div class="home-notice-list"><a href="#archive"><span class="notice-icon" aria-hidden="true">${hubIcon('book')}</span><div><h3>Who has the past question?</h3><p>Check the archive before you send that message.</p></div></a><a href="#hostel-complaints"><span class="notice-icon" aria-hidden="true">${hubIcon('home')}</span><div><h3>Hostel wahala?</h3><p>See the rules area or tell SCF what needs fixing.</p></div></a><a href="#school-links"><span class="notice-icon" aria-hidden="true">${hubIcon('link')}</span><div><h3>Looking for your portal?</h3><p>Find the official school services in one place.</p></div></a></div></div></div></section>
<section class="section home-campus-life"><div class="wrap"><div class="section-head"><div><h2>There’s life outside lectures.</h2><p>Find a good meal, something to join or a reason to get moving.</p></div>${link('explore','Explore the hub')}</div><div class="home-life-grid"><a class="home-life-card" href="#places"><div class="home-life-image"><img src="assets/food.jpg" alt="Illustrative food photography; campus vendors still to be verified" loading="lazy"><span>Illustrative photo</span></div><div><h3>So, what are we eating?</h3><p>Find a spot and check the price range.</p><span class="inline-action">Eat, Drink & Shop</span></div></a><a class="home-life-card" href="#groups"><div class="home-life-image"><img src="assets/mu-symposium.webp" alt="A group photograph from Maduka University’s Students’ Week symposium" loading="lazy"></div><div><h3>Find your people.</h3><p>See what communities you can get involved in.</p><span class="inline-action">Meet the groups</span></div></a><a class="home-life-card" href="#sports"><div class="home-life-image"><img src="assets/basketball.jpg" alt="Illustrative basketball photography; school activities await confirmation" loading="lazy"><span>Illustrative photo</span></div><div><h3>You can’t read all day.</h3><p>Teams, fitness and places to play.</p><span class="inline-action">Sport & Fitness</span></div></a></div></div></section>
<section class="home-ad-section"><div class="wrap">${ad()}</div></section>
<section class="section home-help-section"><div class="wrap home-help-grid"><div class="home-help-copy"><h2>We’re students too.</h2><p>We know how much of school runs on “ask someone”. This is our way of making the answers easier to find, and giving you somewhere to raise the things that need attention.</p>${btn('ask-scf','Ask us','navy')}<a href="#issues" class="link">Academic complaints</a></div><aside class="home-travel-card"><div><h2>Ready to go home?</h2><p>Check your route, fare and departure details before you plan the journey.</p>${btn('travel','See travel home','white')}</div></aside></div></section>`}
const resources=[['COS 101','Introduction to Computing','Past questions','100','Computing','2024/25',['Computer Science','Software Engineering','Cybersecurity']],['MTH 101','Elementary Mathematics I','Notes','100','General Studies','2024/25',['General courses']],['PHY 101','General Physics I','Past questions','100','General Studies','2023/24',['General courses']],['SEN 201','Introduction to Software Engineering','Notes','200','Computing','2024/25',['Software Engineering']],['GST 111','Communication in English','Study materials','100','General Studies','2024/25',['General courses']],['COS 201','Computer Programming I','Past questions','200','Computing','2023/24',['Computer Science','Software Engineering']]];
function archive(){return intro('Looking for that past question?','Search by course, pick what you need and download it. No need to scroll through weeks of group chat messages.',academicTabs('archive'))+`<section class="section"><div class="wrap"><p class="sample-note">Sample resources, faculties and departments for this preview. The official faculty and department list will be added when available.</p><div class="split"><div><div class="archive-filter-panel"><label>Course name or code<input id="resource-search" class="field" type="search" placeholder="e.g. COS 101 or Introduction to Computing"></label><div class="archive-filter-grid"><label>Faculty<select id="resource-faculty" class="field">${reviewOptions(uniqueValues(resources.map(r=>r[4])),'All faculties')}</select></label><label>Department<select id="resource-department" class="field">${reviewOptions(uniqueValues(resources.flatMap(r=>r[6])),'All departments')}</select></label><label>Level<select id="level" class="field"><option value="">All levels</option>${['100','200','300','400','500','600'].map(l=>`<option value="${l}">${l} level</option>`).join('')}</select></label><label>Material type<select id="type" class="field"><option value="">All materials</option><option>Past questions</option><option>Notes</option><option>Study materials</option></select></label></div><button class="clear-review-filters" id="clear-resource-filters">Clear filters</button></div><div class="result-count" id="resource-count" role="status" aria-live="polite"></div><div class="resource-list" id="resources"></div></div>${ad(true)}</div></div></section>`}
function getFilteredResources(records,{query='',faculty='',department='',level='',type=''}={}){const q=query.trim().toLowerCase();return records.filter(r=>(r[0]+' '+r[1]+' '+r[4]+' '+r[6].join(' ')).toLowerCase().includes(q)&&(!faculty||faculty===r[4])&&(!department||r[6].includes(department))&&(!level||level===r[3])&&(!type||type===r[2]))}
function filterResources(){const list=getFilteredResources(resources,{query:document.querySelector('#resource-search').value,faculty:document.querySelector('#resource-faculty').value,department:document.querySelector('#resource-department').value,level:document.querySelector('#level').value,type:document.querySelector('#type').value});document.querySelector('#resource-count').textContent=list.length+(list.length===1?' sample resource':' sample resources');animatedList('#resources').html=list.length?list.map(r=>`<article class="resource" data-motion-key="resource-${esc(r[0])}-${esc(r[5])}"><span class="file-icon">PDF</span><div class="resource-details"><h3>${esc(r[0])} · ${esc(r[1])}</h3><p>${esc(r[2])} &nbsp; · &nbsp; ${esc(r[3])} level &nbsp; · &nbsp; ${esc(r[5])}</p><p class="resource-path">${esc(r[4])} <span aria-hidden="true">›</span> ${r[6].map(esc).join(' · ')}</p></div><button class="btn outline" data-resource="${esc(r[0])}">Preview</button></article>`).join(''):'<div class="empty"><h3>No materials found.</h3><p>Try another course, faculty or department, or clear a filter.</p></div>'}
function refreshResourceDepartments(){const faculty=document.querySelector('#resource-faculty').value,dep=document.querySelector('#resource-department'),selected=dep.value,values=uniqueValues(resources.filter(r=>!faculty||r[4]===faculty).flatMap(r=>r[6]));dep.innerHTML=reviewOptions(values,'All departments');dep.value=values.includes(selected)?selected:'';filterResources()}
function clearResourceFilters(){['resource-search','resource-faculty','resource-department','level','type'].forEach(id=>document.getElementById(id).value='');refreshResourceDepartments()}
function initResourceFilters(){['resource-search','resource-department','level','type'].forEach(id=>document.getElementById(id).addEventListener('input',filterResources));document.querySelector('#resource-faculty').addEventListener('change',refreshResourceDepartments);document.querySelector('#clear-resource-filters').addEventListener('click',clearResourceFilters);if(pendingSearch?.route==='archive'){document.querySelector('#resource-search').value=pendingSearch.query;pendingSearch=null}filterResources()}
const places=[{name:'The Campus Kitchen',cat:'Food',img:'food',price:'₦1,500–₦3,500',desc:'Rice bowls, local favourites and a quick lunch between lectures.',where:'Sample location · Main campus',sponsor:true},{name:'The Coffee Corner',cat:'Drink',img:'coffee',price:'₦800–₦2,500',desc:'Coffee, cold drinks and something small to keep you going.',where:'Sample location · Student centre'},{name:'Everyday Essentials',cat:'Shop',symbol:'bag',price:'₦300–₦10,000',desc:'Stationery, toiletries, snacks and those last-minute necessities.',where:'Sample location · Hostel area'},{name:'Lunch & Co.',cat:'Food',img:'food',price:'₦1,000–₦3,000',desc:'Simple student lunches and takeaway meals.',where:'Sample location · Campus walkway'}];
function placesPage(){return intro('Eat, Drink & Shop.','Find out where to eat, grab a drink or shop in school. Check the price range before you leave your room.')+`<section class="section"><div class="wrap">${note}<div class="filters"><input id="place-search" type="search" placeholder="Find a place or something you need…" aria-label="Search campus places"><select id="price" aria-label="Filter by starting price"><option value="">Any price range</option><option value="1000">Starts at ₦1,000 or less</option><option value="2000">Starts at ₦2,000 or less</option></select></div><div class="chips" id="place-chips" data-motion-tabs="places" role="group" aria-label="Filter campus places">${['All spots','Food','Drink','Shop'].map((x,i)=>`<button class="chip ${i===0?'active':''}" data-category="${x}" aria-pressed="${i===0}">${hubIcon(['pin','food','cup','bag'][i])}<span>${x}</span></button>`).join('')}</div><div class="result-count" id="place-count"></div><div class="listing-grid" id="places"></div><div class="inline-ad">${ad()}</div></div></section>`}
let placeCategory='All spots';function filterPlaces(){const q=document.querySelector('#place-search').value.toLowerCase(),max=+document.querySelector('#price').value;const list=places.filter(p=>(placeCategory==='All spots'||p.cat===placeCategory)&&(p.name+' '+p.desc).toLowerCase().includes(q)&&(!max||+p.price.match(/[\d,]+/)[0].replaceAll(',','')<=max));document.querySelector('#place-count').textContent=list.length+' sample spots · Sponsored listings are labelled; no ratings have been collected.';animatedList('#places').html=list.length?list.map(p=>`<article class="card ${p.sponsor?'sponsored':''}" data-motion-key="place-${slugify(p.name)}">${p.img?`<img src="assets/${p.img}.jpg" alt="Illustrative ${p.cat.toLowerCase()} photography" loading="lazy">`:`<div class="group-symbol" aria-hidden="true">${hubIcon(p.symbol)}</div>`}<div class="card-body"><span class="tag">${p.cat}${p.sponsor?'<span>Sponsored · Sample</span>':''}</span><h3>${p.name}</h3><div class="card-meta"><b>${p.price}</b><span>No ratings yet</span></div><p>${p.desc}</p><p>${p.where}</p><a class="btn outline" href="#place/${slugify(p.name)}">Explore this spot</a></div></article>`).join(''):'<p class="empty">No spots match your filters. Try a different category or price range.</p>'}
const courseReviews=[
{id:1,code:'COS 101',course:'Introduction to Computing',faculty:'Computing',department:'Computer Science',level:'100',rating:4,difficulty:'Manageable',hours:'3–5 hours',title:'Get the basics right early.',experience:'The topics build on each other, so it helps to understand the first few weeks properly. I found the practical examples easier to follow than just reading definitions.',tip:'Make short notes after class and try explaining each topic without looking at them.',sample:true},
{id:2,code:'SEN 201',course:'Introduction to Software Engineering',faculty:'Computing',department:'Software Engineering',level:'200',rating:4,difficulty:'Moderate',hours:'3–5 hours',title:'The examples make it click.',experience:'There are quite a few terms and processes to understand. Connecting them to an app you already use makes the work feel much less abstract.',tip:'Work through the development stages with one small project in mind.',sample:true},
{id:3,code:'CYB 201',course:'Introduction to Cybersecurity',faculty:'Computing',department:'Cybersecurity',level:'200',rating:5,difficulty:'Moderate',hours:'3–5 hours',title:'Keep asking how it works in real life.',experience:'The security concepts were easier to remember when I linked them to everyday situations, like account security and suspicious messages.',tip:'Use the examples from class to test your understanding, then practise with revision questions.',sample:true},
{id:4,code:'MTH 101',course:'Elementary Mathematics I',faculty:'General Studies',department:'General courses',level:'100',rating:3,difficulty:'Challenging',hours:'5–7 hours',title:'Reading the solution isn’t the same as solving it.',experience:'I thought I understood a topic until I tried a question on my own. Regular practice helped much more than leaving everything until a few days before the test.',tip:'Try each question yourself first. When you get stuck, note the exact step you couldn’t follow.',sample:true}
];
const uniqueValues=values=>[...new Set(values)].sort((a,b)=>a.localeCompare(b));
const reviewOptions=(values,all)=>`<option value="">${all}</option>`+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');
function reviews(){return intro('What’s this course actually like?','Find your department, look up a course and hear what helped students get through it. Taken it already? Help the next person out.',academicTabs('reviews'))+`<section class="section reviews-section"><div class="wrap"><div class="reviews-top"><div><h2>Find your course. Get the gist.</h2><p>Search a name or code, or narrow it down to your faculty and department.</p></div><button class="btn navy" data-review>Review a course</button></div><p class="sample-note">Sample faculties, departments and reviews for now. We’ll add the official list when it’s available. Reviews you add here stay in this tab until you refresh; they aren’t sent or published.</p><div class="review-filter-panel"><div class="review-search-row"><label class="review-search-label">Course name or code<input type="search" id="course-query" class="field" placeholder="e.g. COS 101 or Introduction to Computing"></label><label>Sort by<select id="course-sort" class="field"><option value="recent">Most recent</option><option value="rating">Highest rated</option><option value="name">Course name A–Z</option></select></label></div><div class="review-filter-row"><label>Faculty<select id="course-faculty" class="field">${reviewOptions(uniqueValues(courseReviews.map(r=>r.faculty)),'All faculties')}</select></label><label>Department<select id="course-department" class="field">${reviewOptions(uniqueValues(courseReviews.map(r=>r.department)),'All departments')}</select></label><label>Level<select id="course-level" class="field">${reviewOptions(['100','200','300','400','500','600'],'All levels')}</select></label><button class="clear-review-filters" id="clear-course-filters">Clear filters</button></div></div><div class="review-results-bar"><p id="course-result-count" role="status" aria-live="polite"></p><span>Student experiences, not official course assessments.</span></div><div class="split reviews-split"><div id="course-review-list"></div><div class="review-sidebar"><div class="review-help"><h3>What makes a useful review?</h3><p>Tell us what the workload was like, what you found tricky and what helped. A few honest details go a long way.</p><p>Keep it about the course and your experience. Academic complaints have their own private page.</p><a class="link" href="#issues">Raise an academic issue</a></div>${ad(true)}</div></div></div></section>`}
function getFilteredCourseReviews(records,{query='',faculty='',department='',level='',sort='recent'}={}){let list=records.filter(r=>(!faculty||r.faculty===faculty)&&(!department||r.department===department)&&(!level||r.level===level)&&(!query||[r.code,r.course,r.faculty,r.department].join(' ').toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())));return list.sort((a,b)=>sort==='rating'?b.rating-a.rating||b.id-a.id:sort==='name'?a.course.localeCompare(b.course)||b.id-a.id:b.id-a.id)}
function reviewParagraphs(s){return String(s).split(/\n+/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}
function courseReviewCard(r){return `<article class="course-review-card" data-motion-key="course-${r.id}"><div class="course-card-heading"><div><div class="course-code-row"><span class="course-code">${esc(r.code)}</span><span class="review-origin">${r.sample?'Sample review':'Your preview review'}</span></div><h3>${esc(r.course)}</h3><p class="course-path">${esc(r.faculty)} <span aria-hidden="true">›</span> ${esc(r.department)} <span aria-hidden="true">·</span> ${esc(r.level)} level</p></div><div class="course-rating" aria-label="Rated ${r.rating} out of 5"><b>${r.rating}<small>/5</small></b><span>Overall experience</span></div></div><div class="course-quick-facts"><span>Difficulty <b>${esc(r.difficulty)}</b></span><span>Study time per week <b>${esc(r.hours)}</b></span></div><div class="review-writing"><h4>${esc(r.title)}</h4>${reviewParagraphs(r.experience)}${r.tip?`<blockquote class="review-tip"><span class="tip-label">What helped</span><div class="tip-quote">${reviewParagraphs(r.tip)}</div></blockquote>`:''}</div><div class="course-card-bottom"><span>${r.sample?'Illustrative student experience':'Added to this preview only · not published'}</span><button class="text-button" data-review-course="${r.id}">Taken this course? Add yours</button></div></article>`}
function filterCourseReviews(){const list=getFilteredCourseReviews(courseReviews,{query:document.querySelector('#course-query').value,faculty:document.querySelector('#course-faculty').value,department:document.querySelector('#course-department').value,level:document.querySelector('#course-level').value,sort:document.querySelector('#course-sort').value});const count=new Set(list.map(r=>[r.code.toUpperCase(),r.course.toLowerCase(),r.faculty,r.department].join('|'))).size;document.querySelector('#course-result-count').textContent=`${list.length} ${list.length===1?'review':'reviews'} across ${count} ${count===1?'course':'courses'}`;animatedList('#course-review-list').html=list.length?list.map(courseReviewCard).join(''):`<div class="reviews-empty"><h3>Nothing here yet.</h3><p>Try another course or clear a filter. If you’ve taken this course, you can be the first to review it.</p><button class="btn navy" data-review>Review a course</button></div>`}
function refreshReviewDepartments(){const faculty=document.querySelector('#course-faculty').value,dep=document.querySelector('#course-department'),current=dep.value,values=uniqueValues(courseReviews.filter(r=>!faculty||r.faculty===faculty).map(r=>r.department));dep.innerHTML=reviewOptions(values,'All departments');if(values.includes(current))dep.value=current;filterCourseReviews()}
function initCourseReviews(){['course-query','course-department','course-level','course-sort'].forEach(id=>document.getElementById(id).addEventListener('input',filterCourseReviews));document.querySelector('#course-faculty').addEventListener('change',refreshReviewDepartments);document.querySelector('#clear-course-filters').addEventListener('click',()=>{['course-query','course-faculty','course-department','course-level'].forEach(id=>document.getElementById(id).value='');document.querySelector('#course-sort').value='recent';refreshReviewDepartments()});if(pendingSearch?.route==='reviews'){document.querySelector('#course-query').value=pendingSearch.query;pendingSearch=null}filterCourseReviews()}
function addPreviewCourseReview(fields){const r={id:Math.max(...courseReviews.map(r=>r.id),0)+1,code:String(fields.code||'').trim().toUpperCase(),course:String(fields.course||'').trim(),faculty:String(fields.faculty||'').trim(),department:String(fields.department||'').trim(),level:String(fields.level||''),rating:Number(fields.rating),difficulty:String(fields.difficulty||''),hours:String(fields.hours||''),title:String(fields.title||'').trim(),experience:String(fields.experience||'').trim(),tip:String(fields.tip||'').trim(),sample:false};if(!r.code||!r.course||!r.faculty||!r.department||!['100','200','300','400','500','600'].includes(r.level)||![1,2,3,4,5].includes(r.rating)||!['Easy','Manageable','Moderate','Challenging','Very challenging'].includes(r.difficulty)||!['Under 3 hours','3–5 hours','5–7 hours','Over 7 hours'].includes(r.hours)||r.title.length<5||r.experience.length<20)throw Error('Please complete the course details and tell us a little more about your experience.');if(r.code.length>20||r.course.length>120||r.faculty.length>100||r.department.length>100||r.title.length>100||r.experience.length>2000||r.tip.length>1000)throw Error('One of your answers is too long. Please shorten it and try again.');courseReviews.push(r);return r}
function openCourseReview(id){const course=courseReviews.find(r=>String(r.id)===String(id));show(`<h2>Taken the course?<br>Tell us how it went.</h2><p class="course-form-intro">A little detail could save someone a lot of guessing.</p><p class="sample-note">Preview only. Your review will appear in this tab and disappear on refresh. It won’t be sent or published. The live service will moderate reviews.</p><form id="course-review-form" class="course-review-form"><fieldset><legend>Which course?</legend><div class="course-form-grid"><label>Course code <span aria-hidden="true">*</span><input class="field" name="code" maxlength="20" required placeholder="e.g. COS 101" value="${esc(course?.code||'')}"></label><label>Course name <span aria-hidden="true">*</span><input class="field" name="course" maxlength="120" required placeholder="e.g. Introduction to Computing" value="${esc(course?.course||'')}"></label><label>Faculty <span aria-hidden="true">*</span><input class="field" id="review-write-faculty" name="faculty" list="faculty-suggestions" maxlength="100" required placeholder="Choose a suggestion or type yours" value="${esc(course?.faculty||'')}"><datalist id="faculty-suggestions">${uniqueValues(courseReviews.map(r=>r.faculty)).map(f=>`<option value="${esc(f)}"></option>`).join('')}</datalist></label><label>Department <span aria-hidden="true">*</span><input class="field" name="department" id="review-write-department" list="department-suggestions" maxlength="100" required placeholder="Choose a suggestion or type yours" value="${esc(course?.department||'')}"><datalist id="department-suggestions"></datalist></label><label>Course level <span aria-hidden="true">*</span><select class="field" name="level" required><option value="">Choose level</option>${['100','200','300','400','500','600'].map(l=>`<option value="${l}" ${course?.level===l?'selected':''}>${l} level</option>`).join('')}</select></label></div></fieldset><fieldset><legend>What was it like?</legend><div class="course-form-grid"><label>Overall experience <span aria-hidden="true">*</span><select class="field" name="rating" required><option value="">Choose a rating</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} out of 5</option>`).join('')}</select></label><label>Difficulty <span aria-hidden="true">*</span><select class="field" name="difficulty" required><option value="">Choose difficulty</option><option>Easy</option><option>Manageable</option><option>Moderate</option><option>Challenging</option><option>Very challenging</option></select></label><label>Study time per week <span aria-hidden="true">*</span><select class="field" name="hours" required><option value="">Choose a range</option><option>Under 3 hours</option><option>3–5 hours</option><option>5–7 hours</option><option>Over 7 hours</option></select></label></div><label>A short headline <span aria-hidden="true">*</span><input class="field" name="title" minlength="5" maxlength="100" required placeholder="e.g. Keep up with the practicals"></label><label>Your experience <span aria-hidden="true">*</span><textarea class="field" name="experience" required minlength="20" maxlength="2000" rows="5" placeholder="What was the workload like? What did you find easy or difficult?"></textarea></label><label>What helped? <span class="optional">Optional</span><textarea class="field" name="tip" maxlength="1000" rows="3" placeholder="Study habits or resources you’d recommend to the next student"></textarea></label></fieldset><p class="form-small-print">Fields marked * are required. Focus on the course; avoid personal details or naming other students.</p><p id="course-form-error" class="course-form-error" role="alert"></p><div class="course-form-actions"><button class="btn navy" type="submit">Add to my preview</button><button class="btn outline" type="button" data-close>Cancel</button></div></form>`);const f=document.querySelector('#review-write-faculty'),updateSuggestions=()=>{const typed=f.value.trim().toLowerCase();document.querySelector('#department-suggestions').innerHTML=uniqueValues(courseReviews.filter(r=>!typed||r.faculty.toLowerCase()===typed).map(r=>r.department)).map(d=>`<option value="${esc(d)}"></option>`).join('')};f.addEventListener('input',updateSuggestions);updateSuggestions();document.querySelector('#course-review-form').addEventListener('submit',e=>{e.preventDefault();try{const fields=Object.fromEntries(new FormData(e.currentTarget).entries());const added=addPreviewCourseReview(fields);modal.close();if(location.hash!=='#reviews')location.hash='#reviews';else route();document.querySelector('#course-query').value=added.code;document.querySelector('#course-faculty').value=added.faculty;refreshReviewDepartments();document.querySelector('#course-department').value=added.department;filterCourseReviews();document.querySelector('#course-result-count').textContent+=' · Your review was added to this preview only.'}catch(error){document.querySelector('#course-form-error').textContent=error.message}})}
const hostelRules=[];
function renderHostelRules(){return `<section class="hostel-rules-panel" id="hostel-rules"><h2>Hostel rules.</h2><p>Read the rules here, or go straight to the complaint form below.</p>${hostelRules.length?`<div class="hostel-rule-files">${hostelRules.map(file=>`<a href="${esc(file.url)}" target="_blank" rel="noopener noreferrer">${esc(file.title)}</a>`).join('')}</div>`:'<div class="rules-empty"><b>No hostel rules uploaded yet.</b><p>SCF will add the approved documents here. You can still raise a complaint below.</p></div>'}<div class="guide-official-link">${officialAnchor('prospectus','Read the university prospectus','btn outline')}<a class="btn navy" href="#complaint-form-heading" data-jump-complaint>Make a hostel complaint</a></div></section>`}
function complaintForm(kind){const categories=kind==='academic'?['Course registration','Results or assessment','Timetable clash','Learning resources','Other academic concern']:kind==='hostel'?['Water or power','Room or maintenance','Cleanliness or sanitation','Room allocation','Hostel rules or conduct','Other hostel concern']:['Student welfare','Campus facilities','Student services','Suggestion','Other concern'];return `<p class="sample-note">Design preview only. This form does not send, store or email complaints. Use sample details when trying it.</p><form class="issue-form scf-complaint-form" id="scf-complaint-form"><label>What’s it about?<select class="field" name="category" required><option value="">Choose a category</option>${categories.map(c=>`<option>${c}</option>`).join('')}</select></label>${kind==='academic'?'<label>Course code, if relevant<input class="field" name="course" maxlength="30" placeholder="e.g. COS 101"></label>':kind==='hostel'?'<label>Hostel or block<input class="field" name="hostel" required maxlength="120" placeholder="Use a sample hostel name in this preview"></label><label>Room or location, if relevant<input class="field" name="location" maxlength="120" placeholder="e.g. Room 12 or the ground-floor corridor"></label>':''}<label>Tell us what happened<textarea class="field" name="message" required minlength="20" maxlength="4000" placeholder="Explain the issue and what you need help with. Use sample text for now."></textarea></label><label>Where should we reply?<input type="email" class="field" name="replyEmail" required maxlength="254" placeholder="For the preview: student@example.com"></label><button class="btn navy" type="submit">Preview my complaint</button></form>`}
function complaintPage(kind){const content={general:{title:'Need help? Ask us.',desc:'Something bothering you in school? Tell SCF what’s going on, or point us towards something that needs fixing.'},academic:{title:'Something wrong? Let’s hear it.',desc:'Having trouble with registration, a result or a course? Explain what’s happening so SCF can follow it up.'},hostel:{title:'Hostel wahala? Tell us.',desc:'Something wrong in your hostel? Check the rules, explain the issue and let SCF know where help is needed.'}}[kind];return intro(content.title,content.desc,kind==='academic'?academicTabs('issues'):'')+`<section class="section"><div class="wrap"><div class="scf-support-banner"><div><span class="support-dot" aria-hidden="true"></span><b>SCF support, 24/7.</b></div><p>You can reach us any time. The first available member of the team can pick up your complaint and reply.</p></div>${kind==='hostel'?renderHostelRules():''}<div class="complaint-layout"><aside class="complaint-side"><h2>We’re listening.</h2><p>In the live service, all SCF members will receive a notification when you raise a complaint.</p><ol><li>Tell us what happened.</li><li>An available member picks it up.</li><li>We reply through your case and email.</li></ol><p>The member handling it will be shown on the case so you don’t get crossed replies.</p>${kind==='general'?`<div class="complaint-other-routes">${btn('issues','Academic complaints','outline')}${btn('hostel-complaints','Hostel complaints','outline')}</div>`:''}${officialAnchor('contact','Need the university directly?','link')}</aside><div><h2 id="complaint-form-heading">${kind==='hostel'?'Make a hostel complaint.':kind==='academic'?'Raise an academic issue.':'Tell us what’s up.'}</h2>${complaintForm(kind)}<details data-accordion-icon="shield"><summary>Who will see my complaint?</summary><p>The planned service will email all SCF members a notification with a link to the secured complaint inbox. Complaint details will stay in that inbox, with access managed through staff accounts. Authorised members can claim a case before replying.</p></details><details data-accordion-icon="chat"><summary>Will this preview email anyone?</summary><p>No. Email delivery will be enabled in the full app after the SCF recipient list, sender account and secure inbox are configured.</p></details></div></div></div></section>`}
function askScf(){return complaintPage('general')}
function hostelComplaints(){return complaintPage('hostel')}
function issues(){return complaintPage('academic')}
function initComplaintForm(kind){document.querySelector('#scf-complaint-form').addEventListener('submit',e=>{e.preventDefault();const label=kind==='hostel-complaints'?'Hostel complaint':kind==='issues'?'Academic complaint':'SCF complaint';show(`<h2>This is how your confirmation will look.</h2><div class="complaint-confirmation"><b>${label}</b><p>Your live case will receive a reference number and start as “Waiting for SCF”. All SCF members will receive a notification, and the first available officer can claim it before replying.</p></div><p class="sample-note">Preview only. No complaint was created and no emails were sent.</p><button class="btn navy" data-close>Back to the form</button>`);e.target.reset()})}
