function officialAnchor(id,text,cls='btn navy'){const item=officialLinks.find(l=>l.id===id);return `<a class="${cls}" href="${item.url}" target="_blank" rel="noopener noreferrer">${text}<span class="sr-only"> (official website, opens in a new tab)</span></a>`}
function schoolLinks(){return intro('Need the official stuff?','The portal, forms, school contacts and other links you keep asking for. Here’s where to click.')+`<section class="section"><div class="wrap"><div class="official-source-note"><p><b>From Maduka University’s official website.</b> Links checked against the published website on 16 October 2026. Requirements can change; read the current official instructions before acting.</p><a href="https://madukauniversity.edu.ng/" target="_blank" rel="noopener noreferrer">Visit Maduka’s website</a></div><div class="filters"><input type="search" id="school-link-search" placeholder="Search for a portal, form, result or contact…" aria-label="Search school links"><select id="school-link-category" aria-label="Filter school links by category">${reviewOptions(uniqueValues(officialLinks.map(l=>l.category)),'All school links')}</select></div><p id="school-link-count" class="result-count" role="status" aria-live="polite"></p><div class="official-link-grid" id="official-link-list"></div><section class="school-contact-panel"><div><h2>Still need someone to ask?</h2><p>Use the university’s published contacts for official help.</p><address>Along Nsukka–Enugu New Road, Ekwegbe, Enugu State, Nigeria</address></div><div class="school-contact-options"><a href="mailto:info@madukauniversity.edu.ng">General enquiries: info@madukauniversity.edu.ng</a><a href="mailto:admission@madukauniversity.edu.ng">Admissions: admission@madukauniversity.edu.ng</a><a href="tel:+2348055091802">08055091802</a><a href="tel:+2349157893107">09157893107</a>${officialAnchor('contact','View official contact page','link')}</div></section><p class="school-source-footer">Sources: ${officialAnchor('contact','Contact page','source-link')} · ${officialAnchor('portal','Student portal','source-link')} · ${officialAnchor('prospectus','Prospectus','source-link')} · <a href="https://madukauniversity.edu.ng/" target="_blank" rel="noopener noreferrer">University website</a>. Some services require school login details. SCF Students’ Hub is separate from these university systems.</p></div></section>`}
function getFilteredSchoolLinks(records,{query='',category=''}={}){const q=query.trim().toLowerCase();return records.filter(l=>(!category||l.category===category)&&[l.title,l.category,l.description,l.instruction].join(' ').toLowerCase().includes(q))}
function filterSchoolLinks(){const list=getFilteredSchoolLinks(officialLinks,{query:document.querySelector('#school-link-search').value,category:document.querySelector('#school-link-category').value});document.querySelector('#school-link-count').textContent=list.length+' official '+(list.length===1?'link':'links');animatedList('#official-link-list').html=list.length?list.map(l=>`<article class="official-link-card" data-motion-key="link-${l.id}"><h2>${l.title}</h2><p>${l.description}</p><div class="where-to-click"><b>Where to click</b><p>${l.instruction}</p></div>${officialAnchor(l.id,'Open '+l.title.toLowerCase())}</article>`).join(''):'<div class="empty"><h3>No matching links.</h3><p>Try “forms”, “results”, “fees” or clear the category filter.</p></div>'}
function initSchoolLinks(){['school-link-search','school-link-category'].forEach(id=>document.getElementById(id).addEventListener('input',filterSchoolLinks));filterSchoolLinks()}
