function freshers(){return intro('New here? Let’s help you settle in.','The things you’ll want to know before arriving, plus the official pages and forms you need to get started.')+`<section class="section"><div class="wrap"><div class="official-source-note"><p><b>Start with the school’s instructions.</b> This guide points you to Maduka’s official information. Checked on 16 October 2026; always read the latest requirements for your session.</p>${btn('school-links','All school links','navy')}</div><div class="guide-layout"><aside class="guide-nav" aria-label="Freshers’ guide sections">${guides.map((g,i)=>`<a href="#guide-${i}">${hubIcon(guideIcons[i])}<span>${g[0]}</span></a>`).join('')}</aside><div><img class="sport-banner" src="assets/mu-female-hostel.webp" alt="A hostel building at Maduka University" loading="lazy">${guides.map((g,i)=>`<details id="guide-${i}" data-accordion-icon="${guideIcons[i]}" ${i===0?'open':''}><summary>${g[0]}</summary><p>${g[1]}</p><div class="guide-official-link">${officialAnchor(g[2],g[3])}${i===4?officialAnchor('results','Open the results portal','btn outline'):i===6?officialAnchor('library','Find library resources','btn outline'):''}${i===7?btn('ask-scf','Ask us','outline'):i===3?btn('hostel-complaints','Hostel complaints','outline'):''}</div></details>`).join('')}<div class="guide-extra-help"><h3>Looking for a room number or a campus shortcut?</h3><p>We’ll add verified local directions and student tips as SCF confirms them. For now, ${officialAnchor('contact','ask the university','source-link')} for exact office locations and accommodation help.</p></div><div class="inline-ad">${ad()}</div></div></div></div></section>`}
const groups=[['code','Academic & Tech','Computing Community','Build, learn and exchange ideas with students interested in technology.'],['heart','Faith & Fellowship','Campus Fellowship','Find a faith community, shared support and regular gatherings.'],['palette','Arts & Creativity','Creative Collective','A space for writing, photography, design and creative experiments.'],['heart','Volunteering','Student Volunteers','Make a difference through service and community projects.'],['globe','Culture & Community','Cultural Society','Celebrate culture, meet people and share traditions.'],['music','Arts & Creativity','Music Community','Meet other musicians, practise together and find your stage.']];
function groupsPage(){return intro('Find your people.','You don’t have to wait for someone to add you to a group. See what’s in school, find what interests you and check how to join.')+`<section class="section"><div class="wrap">${note}<p class="swipe-hint">Swipe or scroll to see all categories.</p><div class="chips" id="group-chips" data-motion-tabs="groups" role="group" aria-label="Filter student groups">${['All groups','Academic & Tech','Faith & Fellowship','Arts & Creativity','Volunteering','Culture & Community'].map((x,i)=>`<button class="chip ${i===0?'active':''}" data-groupcat="${x.replaceAll('&','&amp;')}" aria-pressed="${i===0}">${hubIcon(groupCategoryIcons[x])}<span>${x}</span></button>`).join('')}</div><div class="listing-grid" id="groups"></div><div class="inline-ad">${ad()}</div></div></section>`}
function filterGroups(cat='All groups'){animatedList('#groups').html=groups.filter(g=>cat==='All groups'||g[1]===cat).map(g=>`<article class="card" data-motion-key="group-${slugify(g[2])}"><div class="group-symbol" aria-hidden="true">${hubIcon(g[0])}</div><div class="card-body"><span class="tag">${g[1]}</span><h3>${g[2]}</h3><p>${g[3]}</p><a class="btn outline" href="#group/${slugify(g[2])}">Meet the group</a></div></article>`).join('')}
function sports(){return intro('You can’t read all day.','Want to join a team, find a training session or just move around a bit? Here’s what’s available.')+`<section class="section"><div class="wrap">${note}<img class="sport-banner" src="assets/basketball.jpg" alt="Basketball court and players"><div class="cards">${[['Team sports','Want to play?','Football, basketball and more. Explore teams and how to join.'],['Fitness & wellbeing','Just trying to stay active?','Discover student fitness communities and group sessions.'],['Facilities & fixtures','Where and when?','Find sports spaces, upcoming fixtures and participation details.']].map(g=>`<article class="card"><div class="card-body"><span class="tag">${g[0]}</span><h3>${g[1]}</h3><p>${g[2]}</p><a class="btn outline" href="#sport/${slugify(g[0])}">Explore</a></div></article>`).join('')}</div><div class="inline-ad">${ad()}</div></div></section>`}
const newsItems=[['Student life','Back in school? Here’s what to know.','Here’s where to find study materials, school updates and help when you need it.','students'],['Academics','Need materials? Check the archive.','Search for your course and see which notes and past questions are available.','library'],['Sport & Fitness','What’s happening with campus sports?','Find a team, see what’s coming up and check how to join in.','basketball']];
function news(){return intro('What’s happening in school?','School updates, events and the things you might have missed. Catch up here.')+`<section class="section"><div class="wrap"><div class="official-source-note"><p><b>Looking for university announcements?</b> Read the school’s official news alongside this student-led hub.</p>${officialAnchor('news','Open official school news')}</div>${note}<div class="cards">${newsItems.map((n,i)=>`<article class="card"><img src="${n[3]==='students'?'assets/mu-senate.webp':'assets/'+n[3]+'.jpg'}" alt="${n[3]==='students'?'Maduka University Senate building':'Illustrative '+n[0].toLowerCase()+' photography'}" loading="lazy"><div class="card-body"><span class="tag">${n[0]} · Sample story</span><h3>${n[1]}</h3><p>${n[2]}</p><button class="btn outline" data-news="${i}">Read story</button></div></article>`).join('')}</div><div class="inline-ad">${ad()}</div></div></section>`}
function travel(){return intro('Going home? Start here.','Check the available destinations, fares and departure dates before booking your trip home.')+`<section class="section"><div class="wrap">${note}<div class="section-head"><div><h2>Where are you heading?</h2><p>Sample departures · Dates, fares and capacity require school confirmation.</p></div></div>${[['Enugu','₦3,000','20 December · 9:00 am'],['Abuja','₦25,000','20 December · 7:00 am'],['Lagos','₦35,000','20 December · 6:00 am']].map(t=>`<article class="trip"><div><span class="tag">MADUKA UNIVERSITY →</span><h3>${t[0]}</h3><p>${t[2]} &nbsp; · &nbsp; Sample trip</p></div><span class="trip-price">${t[1]}</span><a class="btn navy" href="#trip/${slugify(t[0])}">View trip</a></article>`).join('')}<details data-accordion-icon="bus"><summary>How will payments and seats work?</summary><p>Students select a trip and upload a transfer receipt. A transport officer verifies payment before confirming a seat. The live service will require school-approved capacity, reservation deadlines, cancellation terms and verified bank details. No payments or bookings are accepted in this preview.</p></details><div class="inline-ad">${ad()}</div></div></section>`}
function show(html){mb.innerHTML=html;modal.showModal();if(motionAllowed()&&typeof modal.animate==='function')modal.animate([{opacity:0,transform:'translateY(10px) scale(.985)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:180,easing:'cubic-bezier(.2,.7,.2,1)'})}
function sampleDetail(title,body){show(`<span class="tag">DESIGN PREVIEW</span><h2>${esc(title)}</h2><p>${body}</p><button class="btn navy" data-close>Got it</button>`)}
function search(){show('<h2>What are you looking for?</h2><input id="global-search" type="search" class="field" placeholder="Try past questions, food, travel…" aria-label="Search all pages"><div id="global-results"></div>');const input=document.querySelector('#global-search');input.addEventListener('input',()=>globalResults(input.value));globalResults('');input.focus()}
const searchPages=[['explore','Explore the hub','All sections, group profiles, campus spots, sports, fitness, trips'],['ask-scf','Ask SCF','Help, student welfare, complaints, 24/7 support'],['hostel-complaints','Hostel complaints & rules','Accommodation, water, power, maintenance, hostel documents'],['school-links','Official school links','Portal, results, fees, forms, registration, contacts, admissions, e-learning, library'],['archive','Study materials & past questions','Academics, notes, resources, courses'],['reviews','Course reviews','Difficulty, workload, student experiences'],['issues','Academic issues','Complaints, results, support'],['freshers','Freshers’ guide','Registration, hostels, contacts'],['places','Eat, Drink & Shop','Food, prices, shopping, coffee'],['groups','Student groups','Faith, technology, creativity, volunteering'],['sports','Sport & Fitness','Teams, training, football, basketball'],['news','News & Events','Updates, announcements, stories'],['travel','Travel home','Bus, transport, booking']];
function getHubSearchResults(q){const query=q.trim().toLowerCase();const pages=searchPages.map(p=>({route:p[0],title:p[1],description:p[2]}));if(!query)return pages;const specific=[...resources.map(r=>({route:'archive',title:r[0]+' · '+r[1],description:r[2]+' · '+r[3]+' level',filter:r[0]})),...courseReviews.map(r=>({route:'reviews',title:r.code+' · '+r.course,description:'Course review · '+r.department,filter:r.code})),...groups.map(g=>({route:'group/'+slugify(g[2]),title:g[2],description:g[1]})),...places.map(p=>({route:'place/'+slugify(p.name),title:p.name,description:p.cat+' · '+p.price}))];return [...specific,...pages].filter(p=>(p.title+' '+p.description).toLowerCase().includes(query)).slice(0,16)}
function globalResults(q){const results=getHubSearchResults(q);document.querySelector('#global-results').innerHTML=results.length?results.map(p=>`<a class="search-result" href="#${p.route}" ${p.filter?`data-search-target="${p.route}" data-search-query="${esc(p.filter)}"`:'data-close'}><b>${esc(p.title)}</b><small>${esc(p.description)}</small></a>`).join(''):'<p>No results yet. Try a course code, “food”, “forms” or “transport”.</p>'}
const slugify=s=>String(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const detailSample='<p class="sample-note">Design preview · The listings, prices, schedules and activities below are illustrative, not verified Maduka services or events. Contact and joining details will be added after confirmation.</p>';
function detailHeader(parent,title,desc){const parentTitle={places:'Eat, Drink & Shop',groups:'Groups',sports:'Sport & Fitness',news:'News & Events',travel:'Travel home'}[parent];return `<div class="page-intro detail-page-intro"><div class="wrap"><div class="breadcrumb"><a href="#home">The Hub</a> <span aria-hidden="true">›</span> <a href="#${parent}">${parentTitle}</a> <span aria-hidden="true">›</span> ${esc(title)}</div><h1>${esc(title)}</h1><p class="lede">${esc(desc)}</p></div></div>`}
function exploreIndex(){return intro('Go on, have a look around.','All the places this hub can take you. Open a section, then try its explore buttons.')+`<section class="section"><div class="wrap"><div class="explore-index-grid">${[['archive','library','Academic Archive','Search by course, faculty or department.'],['reviews','library','Course Reviews','See what the workload is like and what helped.'],['freshers','students','Freshers’ Guide','The basics, plus official school links.'],['places','food','Eat, Drink & Shop','Food spots, shops, prices and student feedback.'],['groups','students','Groups','Find a community and explore its profile.'],['sports','basketball','Sport & Fitness','Teams, fitness sessions, facilities and fixtures.']].map(c=>`<a class="explore-index-card" href="#${c[0]}"><img src="${c[1]==='students'?'assets/mu-campus.webp':'assets/'+c[1]+'.jpg'}" alt="" loading="lazy"><div><h2>${c[2]}</h2><p>${c[3]}</p><span>Explore</span></div></a>`).join('')}</div><section class="detail-preview-index"><h2>A closer look.</h2><p>Open the individual pages behind the explore buttons. These use sample content.</p><div class="preview-link-columns"><div><h3>Group profiles</h3>${groups.map(g=>`<a href="#group/${slugify(g[2])}">${g[2]}</a>`).join('')}</div><div><h3>Campus spots</h3>${places.map(p=>`<a href="#place/${slugify(p.name)}">${p.name}</a>`).join('')}</div><div><h3>Sport & Fitness</h3>${sportDetailData.map(s=>`<a href="#sport/${s.slug}">${s.title}</a>`).join('')}<h3>Also explore</h3><a href="#news">News & Events</a><a href="#travel">Travel home</a><a href="#school-links">Official school links</a><a href="#ask-scf">Ask SCF</a><a href="#hostel-complaints">Hostel complaints & rules</a></div></div></section></div></section>`}
const groupActivities={
'Academic & Tech':[['Build something small.','Bring a project idea, ask questions and try things out with other students.'],['Learn from each other.','Student-led sessions, practical demos and help getting unstuck.'],['Show what you made.','Share your work and get useful feedback.']],
'Faith & Fellowship':[['Gather together.','A place for prayer, worship and conversation.'],['Support each other.','Build friendships and look out for one another.'],['Serve together.','Take part in community projects and group activities.']],
'Arts & Creativity':[['Make something.','Bring your writing, photos, designs or music and keep creating.'],['Share the process.','Workshop ideas and learn from people with different creative interests.'],['Find an audience.','Take part in showcases and collaborative projects.']],
'Volunteering':[['Lend a hand.','Discover student-led ways to help around campus and beyond.'],['Join a project.','Work with a team on a practical community need.'],['Make it count.','Bring your skills and learn something while contributing.']],
'Culture & Community':[['Share your culture.','Connect through stories, traditions and shared experiences.'],['Meet someone new.','Get to know students from different backgrounds.'],['Celebrate together.','Help organise gatherings and cultural activities.']]
};
function groupDetail(g){const activity=groupActivities[g[1]],related=groups.filter(other=>other!==g).slice(0,2);return detailHeader('groups',g[2],g[3])+`<section class="section"><div class="wrap">${detailSample}<div class="detail-hero-grid"><div class="group-profile-art"><img src="assets/mu-symposium.webp" alt="Maduka University Students’ Week symposium; illustrative cover for this sample group" loading="lazy"><span class="profile-art-symbol" aria-hidden="true">${hubIcon(g[0])}</span><span class="profile-art-caption">A few shared interests.<br>A lot to talk about.</span></div><aside class="detail-side-card"><span class="profile-category">${g[1]}</span><h2>Sounds like your kind of people?</h2><p>Open to interested students. You don’t need to have everything figured out before joining.</p><dl><div><dt>Meeting time</dt><dd>To be confirmed</dd></div><div><dt>Where</dt><dd>Campus location to be added</dd></div><div><dt>Group contact</dt><dd>Awaiting verified details</dd></div></dl><button class="btn navy" data-preview-action="${esc('Joining '+g[2])}">How to join</button></aside></div><div class="detail-section-heading"><h2>What goes on here?</h2><p>A feel for the kinds of activities a group like this can offer.</p></div><div class="detail-activity-grid">${activity.map((a,i)=>`<article><span class="activity-icon" aria-hidden="true">${hubIcon(groupActivityIcons[g[1]][i])}</span><h3>${a[0]}</h3><p>${a[1]}</p></article>`).join('')}</div><div class="detail-content-grid"><section class="detail-body-panel"><h2>Your first time?</h2><p>Have a look at what the group does and bring any questions. The published profile will include a verified joining link and contact person.</p><p>Until those details are confirmed, this preview won’t send you to a random group chat.</p></section><section class="detail-next-event"><h2>Next gathering.</h2><p>No verified event has been posted yet.</p><p>Meeting dates and event details will appear here once the group is listed by SCF.</p>${btn('news','See news & events','outline')}</section></div><div class="detail-section-heading"><h2>Keep looking around.</h2><p>A couple of other communities you can explore.</p></div><div class="related-detail-grid">${related.map(r=>`<a href="#group/${slugify(r[2])}"><span aria-hidden="true">${hubIcon(r[0])}</span><div><h3>${r[2]}</h3><p>${r[1]}</p></div></a>`).join('')}</div><div class="inline-ad">${ad()}</div></div></section>`}
const spotMenus={Food:[['Rice & chicken','₦2,500'],['Rice bowl','₦1,500'],['Local meal','₦3,000']],Drink:[['Coffee','₦1,500'],['Cold drink','₦800'],['Coffee & a snack','₦2,500']],Shop:[['Stationery','From ₦300'],['Toiletries','From ₦1,000'],['Everyday essentials','Prices vary']]};
function placeDetail(p){const menu=spotMenus[p.cat],related=places.filter(other=>other!==p).slice(0,2);return detailHeader('places',p.name,p.desc)+`<section class="section"><div class="wrap">${detailSample}<div class="detail-hero-grid"><div class="spot-profile-visual">${p.img?`<img src="assets/${p.img}.jpg" alt="Illustrative ${p.cat.toLowerCase()} photography">`:`<div class="shop-profile-graphic"><span aria-hidden="true">${hubIcon('bag')}</span><h2>The little<br>things you<br>need.</h2></div>`}${p.sponsor?'<span class="spot-sponsor">Sponsored · Sample placement</span>':''}</div><aside class="detail-side-card"><h2>Before you head out.</h2><dl><div><dt>Price range</dt><dd>${p.price}</dd></div><div><dt>Location</dt><dd>${p.where}</dd></div><div><dt>Opening hours</dt><dd>To be confirmed</dd></div><div><dt>Student rating</dt><dd>No reviews yet</dd></div></dl><button class="btn navy" data-writeplace="${esc(p.name)}">Been here? Leave a review</button><button class="btn outline" data-preview-action="${esc('Finding '+p.name)}">Location & contact</button></aside></div><div class="detail-content-grid"><section><div class="detail-section-heading"><h2>${p.cat==='Shop'?'What you can pick up.':'What’s on offer?'}</h2><p>Illustrative ${p.cat==='Shop'?'products':'menu items'} and prices to show the layout.</p></div><div class="spot-menu-list">${menu.map(m=>`<div><span>${m[0]}</span><b>${m[1]}</b></div>`).join('')}</div></section><section class="detail-body-panel"><h2>Good to know.</h2><p>${p.desc}</p><p>The full listing will include confirmed opening times, directions and contact details supplied by the business and checked by SCF.</p><p>For food and drinks, ask the vendor directly about ingredients or dietary needs.</p></section></div><section class="spot-reviews-section"><div class="section-head"><div><h2>How was it?</h2><p>Student experiences will live here. Paid placements won’t change ratings.</p></div><button class="btn navy" data-writeplace="${esc(p.name)}">Write a review</button></div><div class="spot-review-empty"><span aria-hidden="true">“</span><h3>No reviews yet.</h3><p>Been here before? Tell the next person what to expect.</p></div></section><div class="detail-section-heading"><h2>Other spots to check out.</h2></div><div class="related-detail-grid">${related.map(r=>`<a href="#place/${slugify(r.name)}"><div><h3>${r.name}</h3><p>${r.cat} · ${r.price}</p></div></a>`).join('')}</div><div class="inline-ad">${ad()}</div></div></section>`}
const sportDetailData=[
{slug:'team-sports',title:'Team sports',heading:'Who’s coming to play?',desc:'Want to play regularly, join a team or just find other students who enjoy the game?',items:[['Football','Get a game going.','Team and training information will be listed here.'],['Basketball','Find your court people.','See how to join training and student games.'],['Other sports','There’s room for more.','Additional sports will be added as activities are verified.']]},
{slug:'fitness-wellbeing',title:'Fitness & wellbeing',heading:'A little movement helps.',desc:'You don’t have to be training for anything. Find a group, a session or a reason to get moving.',items:[['Walking & running','Start at your own pace.','Find students interested in group walks or runs.'],['Group fitness','It’s easier with company.','Explore student-led fitness activities.'],['Beginner sessions','No need to know it all.','Find sessions welcoming students who are just starting out.']]},
{slug:'facilities-fixtures',title:'Facilities & fixtures',heading:'Where are we playing?',desc:'Find places to play, check what’s coming up and know where to show up.',items:[['Sports facilities','Find a place to play.','Verified locations and access information will be added here.'],['Upcoming fixtures','Know the next game.','Confirmed matches, dates and teams will appear here.'],['Using a facility','Check before you go.','Opening times, booking instructions and the right contact will be listed.']]}
];
function sportDetail(s){return detailHeader('sports',s.title,s.desc)+`<section class="section"><div class="wrap">${detailSample}<div class="sports-detail-banner"><img src="assets/basketball.jpg" alt="Illustrative basketball court and players"><h2>${s.heading}</h2></div><div class="detail-activity-grid sport-options">${s.items.map((i,n)=>`<article><span class="activity-icon" aria-hidden="true">${hubIcon(({'team-sports':['ball','ball','people'],'fitness-wellbeing':['fitness','heart','people'],'facilities-fixtures':['pin','calendar','check']})[s.slug][n])}</span><h3>${i[0]}</h3><b>${i[1]}</b><p>${i[2]}</p><button class="btn outline" data-preview-action="${esc(i[0])}">View information</button></article>`).join('')}</div><div class="detail-content-grid"><section class="detail-body-panel"><h2>${s.slug==='facilities-fixtures'?'The next fixture.':'Where and when?'}</h2><p>No confirmed ${s.slug==='facilities-fixtures'?'fixtures':'sessions'} yet. Real dates, locations and contacts will appear once SCF has checked them.</p><p>These previews show the page structure, without inventing actual school schedules.</p></section><section class="detail-next-event"><h2>Want to get involved?</h2><p>Ask SCF about current activities, available facilities or how to start something with other students.</p>${btn('ask-scf','Ask us','navy')}</section></div><div class="detail-section-heading"><h2>A bit more to explore.</h2></div><div class="related-detail-grid">${sportDetailData.filter(other=>other!==s).map(r=>`<a href="#sport/${r.slug}"><div><h3>${r.title}</h3><p>${r.heading}</p></div></a>`).join('')}</div><div class="inline-ad">${ad()}</div></div></section>`}
function storyDetail(n){const route=n[0]==='Academics'?'archive':n[0]==='Sport & Fitness'?'sports':'freshers';return detailHeader('news',n[1],n[2])+`<section class="section"><div class="wrap article-detail-wrap"><p class="sample-note">Sample article · This is a preview of the story layout, not a university announcement.</p><img class="article-cover" src="${n[3]==='students'?'assets/mu-senate.webp':'assets/'+n[3]+'.jpg'}" alt="${n[3]==='students'?'Maduka University Senate building':'Illustrative '+n[0].toLowerCase()+' photograph'}" loading="lazy"><div class="article-reading"><p class="article-meta">SCF Students’ Hub · ${n[0]} · Sample story</p><h2>${n[1]}</h2><p class="article-lead">${n[2]}</p><p>There’s plenty to keep track of in school. The hub brings the useful information together so it’s easier to find when you need it.</p><h3>Where to start.</h3><p>Open the relevant section, look for the information you need, and check the official school links for university instructions.</p>${btn(route,'Take a look','navy')}<aside class="article-callout"><b>Need the school’s own announcement?</b><p>Use the official news page for university updates, and check the date before acting.</p>${officialAnchor('news','Read official school news','link')}</aside>${link('news','Back to all news')}</div><div class="inline-ad">${ad()}</div></div></section>`}
const tripDetailData=[{slug:'enugu',name:'Enugu',fare:'₦3,000',departure:'20 December · 9:00 am'},{slug:'abuja',name:'Abuja',fare:'₦25,000',departure:'20 December · 7:00 am'},{slug:'lagos',name:'Lagos',fare:'₦35,000',departure:'20 December · 6:00 am'}];
function tripDetail(t){return detailHeader('travel','Maduka to '+t.name,'Check the trip details and see how your booking will work.')+`<section class="section"><div class="wrap">${detailSample}<div class="trip-detail-layout"><section class="trip-route-panel"><div class="route-endpoint"><span class="route-dot" aria-hidden="true"></span><div><small>Leaving from</small><h2>Maduka University</h2><p>Boarding point to be confirmed</p></div></div><div class="trip-route-line" aria-hidden="true"></div><div class="route-endpoint"><span class="route-dot destination" aria-hidden="true"></span><div><small>Heading to</small><h2>${t.name}</h2><p>Drop-off location to be confirmed</p></div></div><div class="trip-route-facts"><div><span>Sample departure</span><b>${t.departure}</b></div><div><span>Seat availability</span><b>Bookings not open</b></div></div></section><aside class="detail-side-card"><h2>Your trip.</h2><div class="trip-detail-fare">${t.fare}<small>Sample fare per passenger</small></div><p>Departure dates, prices and buses need school confirmation before booking opens.</p><button class="btn navy" data-preview-action="Booking a trip to ${t.name}">Preview booking steps</button><p class="detail-fineprint">No payments, receipts or seat reservations are accepted in this preview.</p></aside></div><section class="booking-steps"><h2>How booking will work.</h2><div class="detail-activity-grid">${[['Choose your trip.','Check the destination, fare and departure details.'],['Send your receipt.','Use the verified payment instructions and submit your transfer receipt.'],['Get confirmation.','A transport officer checks payment and confirms your seat.']].map((s,i)=>`<article><span class="activity-icon" aria-hidden="true">${hubIcon(['bus','receipt','check'][i])}</span><h3>${s[0]}</h3><p>${s[1]}</p></article>`).join('')}</div></section><details data-accordion-icon="calendar"><summary>Can I cancel or change my trip?</summary><p>The school-approved cancellation, change and refund policy must be published before bookings open. Check the terms attached to your actual trip.</p></details><div class="detail-return-link">${link('travel','Back to all destinations')}</div></div></section>`}
function resolveExploreRoute(name){const [kind,slug,...rest]=name.split('/');if(rest.length||!slug)return null;const groupsBySlug=groups.find(g=>slugify(g[2])===slug),place=places.find(p=>slugify(p.name)===slug),sport=sportDetailData.find(s=>s.slug===slug),story=newsItems.find(n=>slugify(n[1])===slug),trip=tripDetailData.find(t=>t.slug===slug);if(kind==='group'&&groupsBySlug)return {parent:'groups',title:groupsBySlug[2],render:()=>groupDetail(groupsBySlug)};if(kind==='place'&&place)return {parent:'places',title:place.name,render:()=>placeDetail(place)};if(kind==='sport'&&sport)return {parent:'sports',title:sport.title,render:()=>sportDetail(sport)};if(kind==='story'&&story)return {parent:'news',title:story[1],render:()=>storyDetail(story)};if(kind==='trip'&&trip)return {parent:'travel',title:'Maduka to '+trip.name,render:()=>tripDetail(trip)};return null}
let pendingSearch=null;
function motionAllowed(){return typeof window.matchMedia==='function'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches}
function animatedList(selector){return {set html(markup){const root=document.querySelector(selector);if(!root)return;if(!motionAllowed()||typeof root.querySelectorAll!=='function'){root.innerHTML=markup;return}const positions=new Map([...root.querySelectorAll('[data-motion-key]')].map(el=>[el.dataset.motionKey,el.getBoundingClientRect()]));root.innerHTML=markup;[...root.querySelectorAll('[data-motion-key]')].forEach((el,i)=>{if(typeof el.animate!=='function')return;const old=positions.get(el.dataset.motionKey),next=el.getBoundingClientRect();if(old){const dx=old.left-next.left,dy=old.top-next.top;if(Math.abs(dx)+Math.abs(dy)>1)el.animate([{transform:`translate(${dx}px,${dy}px)`},{transform:'translate(0,0)'}],{duration:200,easing:'cubic-bezier(.2,.7,.2,1)'})}else el.animate([{opacity:0,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:180,delay:Math.min(i,5)*18,easing:'ease-out'})})}}}
// Native details keep their keyboard behaviour; motion only enhances the transition.
const accordionMotion=new Map();
function setGuideActive(id){
  document.querySelectorAll('.guide-nav a').forEach(link=>{
    const active=link.getAttribute('href')==='#'+id;
    link.classList.toggle('current',active);
    if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');
  });
}
function settleAccordion(details,state){
  const animation=state.animation;
  state.animation=null;
  if(animation){animation.onfinish=null;animation.oncancel=null;animation.cancel()}
  details.open=state.open;
  state.content.inert=!state.open;
  details.style.removeProperty('height');
  details.style.removeProperty('overflow');
  details.removeAttribute('data-animating');
}
function setAccordionOpen(details,open,animate=true){
  const state=accordionMotion.get(details);
  if(!state){details.open=open;return}
  if(!state.animation&&state.open===open)return;
  const start=details.getBoundingClientRect().height;
  if(state.animation){state.animation.onfinish=null;state.animation.oncancel=null;state.animation.cancel();state.animation=null}
  state.open=open;
  if(!open&&state.content.contains(document.activeElement))state.summary.focus({preventScroll:true});
  state.content.inert=!open;
  details.style.removeProperty('height');
  details.style.removeProperty('overflow');
  details.open=open;
  const end=details.getBoundingClientRect().height;
  if(details.id.startsWith('guide-'))setGuideActive(details.id);
  if(!animate||!motionAllowed()||typeof details.animate!=='function'||Math.abs(start-end)<1){settleAccordion(details,state);return}
  details.open=true;
  details.style.height=start+'px';
  details.style.overflow='hidden';
  details.setAttribute('data-animating','true');
  const animation=details.animate([{height:start+'px'},{height:end+'px'}],{duration:280,easing:'cubic-bezier(.22,1,.36,1)'});
  state.animation=animation;
  animation.onfinish=()=>{if(state.animation===animation)settleAccordion(details,state)};
  animation.oncancel=()=>{if(state.animation===animation)settleAccordion(details,state)};
}
function initAccordions(){
  document.querySelectorAll('#app details').forEach(details=>{
    if(accordionMotion.has(details))return;
    const summary=details.querySelector('summary');
    if(!summary)return;
    const content=document.createElement('div');
    content.className='accordion-content';
    [...details.childNodes].filter(node=>node!==summary).forEach(node=>content.append(node));
    details.append(content);
    const icon=document.createElement('span');
    icon.className='summary-icon';
    icon.setAttribute('aria-hidden','true');
    icon.innerHTML=hubIcon(details.dataset.accordionIcon||'chat');
    const label=document.createElement('span');
    label.className='summary-label';
    while(summary.firstChild)label.append(summary.firstChild);
    summary.append(icon,label);
    details.classList.add('motion-details');
    const state={summary,content,open:details.open,animation:null};
    content.inert=!details.open;
    accordionMotion.set(details,state);
    summary.addEventListener('click',event=>{
      if(event.defaultPrevented||event.target.closest('a,button,input,select,textarea'))return;
      event.preventDefault();
      setAccordionOpen(details,!state.open);
    });
  });
  setGuideActive(document.querySelector('.guide-layout details[open]')?.id);
}
function stopPageMotion(){
  accordionMotion.forEach((state,details)=>settleAccordion(details,state));
  clearHomeScrollReveals();
  pageRevealObserver?.disconnect();
  app.getAnimations?.({subtree:true}).forEach(animation=>animation.cancel());
  modal.getAnimations?.({subtree:true}).forEach(animation=>animation.cancel());
}

// The same gliding selection treatment works for page links and filter buttons.
const tabMotionPositions=new Map();
let tabResizeObserver;
function moveTabIndicator(row,animate=true){
  if(!row)return;
  const active=row.querySelector('.selected,[aria-pressed="true"]');
  if(!active)return;
  const bounds=row.getBoundingClientRect();
  const relativeRect=el=>{
    const rect=el.getBoundingClientRect();
    return {left:rect.left-bounds.left+row.scrollLeft-row.clientLeft,top:rect.top-bounds.top+row.scrollTop-row.clientTop,width:rect.width,height:rect.height};
  };
  let indicator=row.querySelector('.tab-glider');
  const previous=indicator?relativeRect(indicator):tabMotionPositions.get(row.dataset.motionTabs);
  const next=relativeRect(active);
  if(!indicator){
    indicator=document.createElement('span');
    indicator.className='tab-glider';
    indicator.setAttribute('aria-hidden','true');
    row.append(indicator);
  }
  indicator.getAnimations?.().forEach(animation=>animation.cancel());
  Object.assign(indicator.style,{left:next.left+'px',top:next.top+'px',width:next.width+'px',height:next.height+'px'});
  row.classList.add('motion-tabs-ready');
  tabMotionPositions.set(row.dataset.motionTabs,next);
  if(animate&&row.clientWidth){
    const end=next.left+next.width;
    const left=next.left<row.scrollLeft+6?Math.max(0,next.left-6):end>row.scrollLeft+row.clientWidth-6?end-row.clientWidth+6:row.scrollLeft;
    if(Math.abs(left-row.scrollLeft)>1)row.scrollTo({left,behavior:motionAllowed()?'smooth':'auto'});
  }
  const changed=previous&&Math.abs(previous.left-next.left)+Math.abs(previous.top-next.top)+Math.abs(previous.width-next.width)>1;
  if(animate&&changed&&next.width&&next.height&&motionAllowed()&&typeof indicator.animate==='function'){
    indicator.animate([
      {transform:`translate(${previous.left-next.left}px,${previous.top-next.top}px) scale(${previous.width/next.width},${previous.height/next.height})`},
      {transform:'translate(0,0) scale(1)'}
    ],{duration:320,easing:'cubic-bezier(.22,1,.36,1)'});
  }
}
function initTabMotion(){
  tabResizeObserver?.disconnect();
  const rows=[...document.querySelectorAll('[data-motion-tabs]')];
  rows.forEach(row=>moveTabIndicator(row));
  if(typeof ResizeObserver==='function'){
    const sizes=new WeakMap();
    tabResizeObserver=new ResizeObserver(entries=>{
      const changed=new Set();
      entries.forEach(({target})=>{
        const rect=target.getBoundingClientRect(),previous=sizes.get(target);
        if(previous&&(Math.abs(previous.width-rect.width)>.5||Math.abs(previous.height-rect.height)>.5))changed.add(target.closest('[data-motion-tabs]'));
        sizes.set(target,{width:rect.width,height:rect.height});
      });
      changed.forEach(row=>moveTabIndicator(row,false));
    });
    rows.forEach(row=>{
      [row,...row.querySelectorAll('a,button')].forEach(item=>{
        const rect=item.getBoundingClientRect();
        sizes.set(item,{width:rect.width,height:rect.height});
        tabResizeObserver.observe(item);
      });
    });
  }
}
let homeScrollObserver;
const homeScrollReveals=new Map();
function finishHomeReveal(el){
  const state=homeScrollReveals.get(el);
  if(state?.animation){
    state.animation.onfinish=null;
    state.animation.oncancel=null;
    state.animation.cancel();
  }
  el.classList.remove('home-reveal-pending');
  el.removeAttribute('data-home-reveal');
  homeScrollObserver?.unobserve(el);
  homeScrollReveals.delete(el);
}
function clearHomeScrollReveals(){
  homeScrollObserver?.disconnect();
  homeScrollReveals.forEach((state,el)=>finishHomeReveal(el));
  homeScrollObserver=null;
}
function revealHomeItem(el,immediate=false){
  const state=homeScrollReveals.get(el);
  if(!state||(state.started&&!immediate))return;
  if(immediate||!motionAllowed()){finishHomeReveal(el);return}
  state.started=true;
  homeScrollObserver?.unobserve(el);
  // Individual translate preserves each card's existing tilt, offset and hover effects.
  const animation=el.animate([
    {opacity:0,translate:'0 24px'},
    {opacity:1,translate:'0 0'}
  ],{duration:1000,delay:state.delay,easing:'cubic-bezier(.22,.61,.36,1)',fill:'both'});
  state.animation=animation;
  el.classList.remove('home-reveal-pending');
  animation.onfinish=()=>finishHomeReveal(el);
  animation.oncancel=()=>finishHomeReveal(el);
}
function initHomeScrollReveals(){
  clearHomeScrollReveals();
  if(!motionAllowed()||typeof IntersectionObserver!=='function')return;
  const compact=window.matchMedia('(max-width:700px)').matches;
  const groups=[
    ['.home-quick-grid>a',110,compact?2:3],
    ['.home-updates .section-head',0,1],
    ['.home-feature-update',0,1],
    ['.home-notice-list>a',90,3],
    ['.home-campus-life .section-head',0,1],
    ['.home-life-card',130,compact?1:3],
    ['.home-ad-section>.wrap',0,1],
    ['.home-help-grid>*',140,compact?1:2]
  ];
  homeScrollObserver=new IntersectionObserver(entries=>{
    entries.forEach(entry=>{if(entry.isIntersecting)revealHomeItem(entry.target)});
  },{threshold:.08,rootMargin:'0px 0px -36px 0px'});
  groups.forEach(([selector,stagger,columns])=>{
    document.querySelectorAll(selector).forEach((el,index)=>{
      if(typeof el.animate!=='function')return;
      homeScrollReveals.set(el,{delay:(index%columns)*stagger,started:false,animation:null});
      el.setAttribute('data-home-reveal','');
      el.classList.add('home-reveal-pending');
      homeScrollObserver.observe(el);
    });
  });
}
let pageRevealObserver;
function polishPageMotion(page=''){
  initTabMotion();
  initAccordions();
  pageRevealObserver?.disconnect();
  if(!motionAllowed())return;
  if(typeof app.animate==='function')app.animate([{opacity:.3},{opacity:1}],{duration:180,easing:'ease-out'});
  if(page==='home'){initHomeScrollReveals();return}
  if(typeof IntersectionObserver!=='function')return;
  const revealOrder=new WeakMap();
  pageRevealObserver=new IntersectionObserver(entries=>{
    entries.forEach(entry=>{
      if(!entry.isIntersecting)return;
      const el=entry.target;
      if(motionAllowed()&&typeof el.animate==='function'){
        const base=window.getComputedStyle(el).transform;
        const transform=base==='none'?'':base;
        el.animate([
          {opacity:.25,transform:`translateY(14px) ${transform}`.trim()},
          {opacity:1,transform:base}
        ],{duration:420,delay:(revealOrder.get(el)||0)*45,easing:'cubic-bezier(.22,1,.36,1)'});
      }
      pageRevealObserver.unobserve(el);
    });
  },{threshold:.1,rootMargin:'0px 0px -16px 0px'});
  document.querySelectorAll('.home-quick-grid>a,.home-feature-update,.home-notice-list>a,.home-life-card,.home-help-grid,.cards>.card,.detail-activity-grid>article,.explore-index-card,.detail-side-card,.detail-body-panel,.detail-next-event,.related-detail-grid>a,.trip').forEach((el,i)=>{
    revealOrder.set(el,i%3);
    pageRevealObserver.observe(el);
  });
}
function initHomeSearch(){document.querySelector('#home-hub-search').addEventListener('submit',e=>{e.preventDefault();const q=document.querySelector('#home-search-query').value.trim();search();document.querySelector('#global-search').value=q;globalResults(q)})}
function route(){
  const requested=location.hash.slice(1)||'home';
  const guideTarget=/^guide-\d+$/.test(requested)&&guides[Number(requested.slice(6))]?'guide-'+Number(requested.slice(6)):null;
  let name=guideTarget?'freshers':requested;
  const pages={home,archive,reviews,issues,freshers,places:placesPage,groups:groupsPage,sports,news,travel,'school-links':schoolLinks,'ask-scf':askScf,'hostel-complaints':hostelComplaints,explore:exploreIndex};
  const detail=resolveExploreRoute(name);
  if(!detail&&!pages[name])name='home';
  const keepGuide=guideTarget&&document.getElementById(guideTarget);
  if(!keepGuide){
    stopPageMotion();
    accordionMotion.clear();
    app.innerHTML=detail?detail.render():pages[name]();
  }
  document.title=(detail?.title||(name==='home'?'SCF Students’ Hub':searchPages.find(p=>p[0]===name)?.[1]||'SCF Students’ Hub'))+' · Maduka University';
  const active=detail?.parent||name;
  document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+active||(['reviews','issues'].includes(active)&&a.hash==='#archive')));
  document.querySelector('nav').classList.remove('open');
  document.querySelector('#menu').setAttribute('aria-expanded','false');
  if(!guideTarget)window.scrollTo(0,0);
  if(!keepGuide){
    if(name==='home')initHomeSearch();
    if(name==='archive')initResourceFilters();
    if(name==='places'){placeCategory='All spots';filterPlaces();['place-search','price'].forEach(id=>document.getElementById(id).addEventListener('input',filterPlaces))}
    if(name==='groups')filterGroups();
    if(name==='school-links')initSchoolLinks();
    if(name==='reviews')initCourseReviews();
    if(['issues','ask-scf','hostel-complaints'].includes(name))initComplaintForm(name);
    polishPageMotion(name);
  }
  if(guideTarget){
    const target=document.getElementById(guideTarget);
    if(target){
      setAccordionOpen(target,true,false);
      setGuideActive(guideTarget);
      target.scrollIntoView({behavior:motionAllowed()?'smooth':'auto',block:'start'});
      target.querySelector('summary').focus({preventScroll:true});
    }
  }
}

